temperatures = {
    "Monday": 72,
    "Tuesday": 68,
    "Wednesday": 75
}

print("Keys:")
for day in temperatures:
    print(day)

print("\nValues:")
for temp in temperatures.values():
    print(temp)

print("\nPairs:")
for day, temp in temperatures.items():
    print(day, "->", temp)
